                                        "properties": {
                                            "message": {"type": "string"},
                                            "query": {"type": "object"},
                                        },
                                        "required": ["message", "query"],
                                        "additionalProperties": True
                                    }
                                }
                            }
                        }
                    },
                }
            }
        },
    }

    schema = schemathesis.openapi.from_dict(schema_dict)
