    base_url = "http://localhost"

    collected_events = []
    dispatcher = events.Dispatcher()
    dispatcher.add_handler(events.AfterExecution, collected_events.append)
    dispatcher.add_handler(events.Failed, collected_events.append)
    dispatcher.add_handler(events.Error, collected_events.append)
    dispatcher.add_handler(events.Interrupted, collected_events.append)
    dispatcher.add_handler(events.InternalError, collected_events.append)

